# ---------------------------------------------------------------- inventory + transforms
def rot(dx, dy, r):
    r %= 360
    if r == 0:
        return dx, dy
    if r == 90:
        return -dy, dx
    if r == 180:
        return -dx, -dy
    if r == 270:
        return dy, -dx
    raise ValueError(r)


def parse_inventory(path):
    parts = {}
    for line in open(path, encoding='utf-8'):
        line = line.strip()
        if not line:
            continue
        f = line.split('|')
        des = f[0]
        w, rest = f[5].split('x', 1)
        h, c = rest.split('(')
        cx, cy = c.rstrip(')').split(',')
        r0 = int(round(float(f[3]))) % 360
        w, h, cx, cy = float(w), float(h), float(cx), float(cy)
        # inventory values are at the captured rotation r0: bring them back to rot 0
        cx, cy = rot(cx, cy, -r0 % 360)
        if r0 % 180:
            w, h = h, w
        pads = []
        for p in f[6].split(';'):
            if not p:
                continue
            num, rest = p.split(':', 1)
            net, xy = rest.rsplit('@', 1)
            dx, dy = (float(v) for v in xy.split(','))
            dx, dy = rot(dx, dy, -r0 % 360)
            net = NET_FIX.get((des, num), net)
            pads.append((num, '' if net == '-' else net, dx, dy))
        parts[des] = {'w': w, 'h': h, 'cx': cx, 'cy': cy, 'pads': pads, 'rot0': r0, 'fp': f[1]}
    for des, o in FOOTPRINT_OVERRIDE.items():
        cur = parts.get(des)
        if cur and len(cur['pads']) == len(o['pads']) and abs(cur['w'] - o['w']) < 40 and abs(cur['h'] - o['h']) < 40:
            continue  # the inventory already has the new footprint
        parts[des] = {'w': o['w'], 'h': o['h'], 'cx': o['cx'], 'cy': o['cy'], 'pads': list(o['pads']), 'rot0': 0,
                      'fp': o['name'], 'override': True, 'pad': o.get('pad', (60.0, 60.0))}
    return parts


def shapes(des, part, x, y, r):
    """Rectangles (x0, y0, x1, y1) that represent the part for collision checks."""
    def rect(w, h, cx, cy):
        cx, cy = rot(cx, cy, r)
        if r % 180:
            w, h = h, w
        return (x + cx - w / 2, y + cy - h / 2, x + cx + w / 2, y + cy + h / 2)
    return [rect(part['w'], part['h'], part['cx'], part['cy'])]


def pads_abs(part, x, y, r):
    out = []
    for num, net, dx, dy in part['pads']:
        px, py = rot(dx, dy, r)
        out.append((num, net, x + px, y + py))
    return out


def overlap(a, b, m=0):
    return min(a[2], b[2]) - max(a[0], b[0]) > -m and min(a[3], b[3]) - max(a[1], b[1]) > -m


def rect_circle_dist(rc, cx, cy):
    dx = max(rc[0] - cx, 0, cx - rc[2])
    dy = max(rc[1] - cy, 0, cy - rc[3])
    return math.hypot(dx, dy)

